//! §5 The standard library, as `Ark.Std` defines it.
//!
//! Everything a function may compute that is not an operator or a read.
//! `trim`, `lower` and `is_alnum` consult the pinned Unicode tables in
//! [`crate::unicode_tables`] (UCD 16.0.0, generated by the spec) and
//! nothing of the platform.
//!
//! §5.1 The list editors — `ListConcat`, `Insert`, `RemoveAt`, `Move`
//! and `Slice` — are what a body edits a list with: two joined, one element
//! put in, one taken out, one moved, and the run between two places. They
//! are few on purpose, since every other edit is made of them: several
//! elements put in at `i` is `ListConcat(ListConcat(Slice(xs, 0, i), ys),
//! Slice(xs, i, len))`, everything after `i` dropped is `Slice(xs, 0, i +
//! 1)`, and the element at `i` is `First(Slice(xs, i, i + 1))`. Until them a
//! list could be mapped, filtered, sorted and folded but never grown, and a
//! domain that edited one wrote each element into a `PerDevice` under a
//! key that sorted where it was to go and read the slots back. What an
//! index may be, and what happens when it is out of range, is [`place`]'s.
//!
//! They came after spec version 4 was written, and are additive: five new
//! names, which a module that calls none of them never carries, so no
//! module, function hash or vector before them moved and `SPEC_VERSION`
//! stays 4. A runtime from before them reads a module that calls one as it
//! reads any module it does not know the words of: `unknown standard
//! function`, at decode, before anything runs.
//!
//! The module is named `stdlib` rather than `std` so that `std::` paths in
//! this crate stay unambiguous.

use std::borrow::Borrow;
use std::collections::BTreeMap;

use crate::ir::StdFn;
use crate::sha256::sha256;
use crate::unicode_tables::{is_alphanumeric, is_white_space, to_lower_simple};
use crate::value::{hex, Id, Value};

/// A fault a standard function can report (`Ark.Std.StdError`). `Arity`
/// and `TypeMismatch` are bugs; `Fault` is a deterministic verdict.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum StdError {
    Arity(StdFn, usize),
    TypeMismatch(StdFn),
    Fault(String),
}

/// Apply a standard function to already-evaluated arguments (`Ark.Std.std`).
///
/// The arguments are borrowed — anything that is a `Value` by reference: a
/// `&Value`, the interpreter's `Cow` of one it read in place, or a `Value`
/// a caller owns — and only what a function returns is copied: `len(xs)`
/// of a bound list counts it where it stands, `first(xs)` copies one
/// element, `contains(xs, x)` compares in place (`docs/plan-perf.md` Round
/// 4). Taking them owned made a call's arguments the price of every call,
/// so `len` of a local list copied the list to count it.
pub fn std<V: Borrow<Value>>(f: StdFn, args: &[V]) -> Result<Value, StdError> {
    if args.len() != f.arity() {
        return Err(StdError::Arity(f, args.len()));
    }
    // Every arity is at most three: the references on the stack, and no
    // list of them built per call.
    let a = |i: usize| args[i].borrow();
    match args.len() {
        0 => apply(f, &[]),
        1 => apply(f, &[a(0)]),
        2 => apply(f, &[a(0), a(1)]),
        _ => apply(f, &[a(0), a(1), a(2)]),
    }
}

fn apply(f: StdFn, args: &[&Value]) -> Result<Value, StdError> {
    use StdFn::*;
    use Value::*;
    let mismatch = || Err(StdError::TypeMismatch(f));
    match (f, args) {
        // text
        (Trim, [Text(t)]) => Ok(Text(t.trim_matches(is_white_space).into())),
        (IsEmpty, [Text(t)]) => Ok(Bool(t.is_empty())),
        (Concat, [List(xs)]) => {
            let mut out = String::with_capacity(xs.iter().map(|x| if let Text(t) = x { t.len() } else { 0 }).sum());
            for x in xs {
                match x {
                    Text(t) => out.push_str(t),
                    _ => return mismatch(),
                }
            }
            Ok(Text(out.into_boxed_str()))
        }
        (Lower, [Text(t)]) => Ok(Text(t.chars().map(to_lower_simple).collect())),
        (IsAlnum, [Text(t)]) => Ok(Bool(!t.is_empty() && t.chars().all(is_alphanumeric))),
        (Chars, [Text(t)]) => Ok(List(t.chars().map(|c| Text(c.encode_utf8(&mut [0; 4]).into())).collect())),
        (TextLen, [Text(t)]) => Ok(Int(t.chars().count() as i64)),
        (StartsWith, [Text(t), Text(p)]) => Ok(Bool(t.starts_with(&**p))),
        (SplitOnce, [Text(t), Text(sep)]) => {
            if sep.is_empty() {
                return Ok(Null);
            }
            Ok(match t.split_once(&**sep) {
                None => Null,
                Some((before, after)) => Value::record(vec![("before", Text(before.into())), ("after", Text(after.into()))]),
            })
        }
        (TextOfInt, [Int(n)]) => Ok(Value::text(n.to_string())),
        (Hex, [Bytes(b)]) => Ok(Value::text(hex(b))),
        // int
        (Min, [Int(a), Int(b)]) => Ok(Int(*a.min(b))),
        (Max, [Int(a), Int(b)]) => Ok(Int(*a.max(b))),
        (Clamp, [Int(x), Int(lo), Int(hi)]) => {
            if lo > hi {
                Err(StdError::Fault("clamp: lower bound above upper bound".into()))
            } else {
                Ok(Int(*lo.max(hi.min(x))))
            }
        }
        (Abs, [Int(n)]) => {
            if *n == i64::MIN {
                Err(StdError::Fault("integer overflow".into()))
            } else {
                Ok(Int(n.abs()))
            }
        }
        // hash
        (Fnv1a64, [Text(t)]) => Ok(Int(fnv1a64(t.as_bytes()) as i64)),
        (Sha256, [Bytes(b)]) => Ok(Value::bytes(sha256(b))),
        // id
        (IdOfText, [Text(t)]) => Ok(id_of_text(t).map(Value::Id).unwrap_or(Null)),
        (TextOfId, [Value::Id(i)]) => Ok(Value::text(text_of_id(i))),
        (NilId, []) => Ok(Value::Id([0; 16])),
        (Utf8, [Text(t)]) => Ok(Bytes(t.as_bytes().into())),
        // list and option
        (First, [List(xs)]) => Ok(xs.first().cloned().unwrap_or(Null)),
        (Last, [List(xs)]) => Ok(xs.last().cloned().unwrap_or(Null)),
        (Len, [List(xs)]) => Ok(Int(xs.len() as i64)),
        (Contains, [List(xs), v]) => Ok(Bool(xs.iter().any(|x| x == *v))),
        (Reverse, [List(xs)]) => Ok(List(xs.iter().rev().cloned().collect())),
        (ListConcat, [List(a), List(b)]) => Ok(List(a.iter().chain(b.iter()).cloned().collect())),
        (Insert, [List(xs), Int(i), x]) => {
            let at = place("insert", *i, xs.len(), true)?;
            let mut out = Vec::with_capacity(xs.len() + 1);
            out.extend_from_slice(&xs[..at]);
            out.push((*x).clone());
            out.extend_from_slice(&xs[at..]);
            Ok(List(out.into()))
        }
        (RemoveAt, [List(xs), Int(i)]) => {
            let at = place("remove_at", *i, xs.len(), false)?;
            Ok(List(xs[..at].iter().chain(&xs[at + 1..]).cloned().collect()))
        }
        (Move, [List(xs), Int(from), Int(to)]) => {
            let from = place("move", *from, xs.len(), false)?;
            let to = place("move", *to, xs.len(), false)?;
            let mut out = xs.to_vec();
            let x = out.remove(from);
            out.insert(to, x);
            Ok(List(out.into()))
        }
        (Slice, [List(xs), Int(start), Int(end)]) => {
            let n = xs.len();
            if *start < 0 || *start > *end || *end > n as i64 {
                return Err(StdError::Fault(format!("slice: {start}..{end} out of range for a list of {n}")));
            }
            Ok(List(xs[*start as usize..*end as usize].into()))
        }
        (IsSome, [v]) => Ok(Bool(!v.is_null())),
        (UnwrapOr, [Null, d]) => Ok((*d).clone()),
        (UnwrapOr, [v, _]) => Ok((*v).clone()),
        (Unwrap, [Null]) => Err(StdError::Fault("unwrapped none".into())),
        (Unwrap, [v]) => Ok((*v).clone()),
        _ => mismatch(),
    }
}

/// §5.1 An index into a list of `n` elements, as the list functions take
/// one: `0..n`, or `0..=n` where the end is a place too (`insert`'s, which
/// may put an element after the last) — so an empty list has no index but
/// `insert`'s 0 — or the refusal `<f>: index <i> out of range for a list of <n>`.
///
/// **An index out of range is a refusal, never clamped**, as an overflow is
/// (§6.5): a body that names a place that is not there has a mistake in
/// it, and moving the place to the nearest one there is would write
/// somewhere the author did not mean, on every replica alike. The words are
/// exact, and every runtime gives them: the function's name in snake_case
/// (`remove_at` for `RemoveAt`), the index as it was given and the list's
/// length, both in decimal. `slice` says both of its bounds:
/// `slice: <start>..<end> out of range for a list of <n>`.
/// A function that takes two indices refuses the first it finds out of
/// range, in the order it takes them; arguments are evaluated before any
/// of this, left to right, so a fault in one is the refusal whatever the
/// index (§6).
///
/// **And a `NonEmpty` is a list here, as everywhere** (§2.2): the checker
/// reads one as `List t` and every list function returns `List t`. Whether
/// a result has an element is held where it crosses a boundary — a live
/// transition's result, an input — so `insert` into a non-empty list, or a
/// non-empty one `ListConcat`ed onto, passes there, and `RemoveAt` or
/// `Slice` leaving none is refused there in the boundary's own words. The
/// authoring vocabulary says the first half in its types: `insert`,
/// `concat` and `move_at` of a `NonEmpty<T>` are `NonEmpty<T>`, and
/// `remove_at` and `slice` of one are a `List<T>` (`spec/AUTHORING.md`
/// §2.2).
fn place(f: &str, i: i64, n: usize, end: bool) -> Result<usize, StdError> {
    if i >= 0 && (i as u64) < n as u64 + u64::from(end) {
        Ok(i as usize)
    } else {
        Err(StdError::Fault(format!("{f}: index {i} out of range for a list of {n}")))
    }
}

/// FNV-1a, 64-bit: offset basis `0xcbf29ce484222325`, prime
/// `0x00000100000001b3`, over the bytes in order.
pub fn fnv1a64(bytes: &[u8]) -> u64 {
    bytes
        .iter()
        .fold(0xcbf29ce484222325u64, |h, b| (h ^ (*b as u64)).wrapping_mul(0x00000100000001b3))
}

/// The canonical text of an id: lowercase 8-4-4-4-12.
pub fn text_of_id(i: &Id) -> String {
    let h = hex(i);
    format!("{}-{}-{}-{}-{}", &h[..8], &h[8..12], &h[12..16], &h[16..20], &h[20..])
}

/// Parse 8-4-4-4-12 hex in either case; anything else is `None`.
pub fn id_of_text(t: &str) -> Option<Id> {
    let parts: Vec<&str> = t.split('-').collect();
    if parts.len() != 5 {
        return None;
    }
    let lens = [8, 4, 4, 4, 12];
    for (p, want) in parts.iter().zip(lens) {
        if p.chars().count() != want || !p.chars().all(|c| c.is_ascii_hexdigit()) {
            return None;
        }
    }
    let bytes = crate::value::decode_hex(&parts.concat())?;
    bytes.as_slice().try_into().ok()
}

/// Arguments (or autos) by name (`Ark.Eval.Args`).
pub type Args = BTreeMap<String, Value>;

#[cfg(test)]
mod tests {
    use super::*;

    fn call(f: StdFn, args: &[Value]) -> Result<Value, StdError> {
        std(f, args)
    }

    #[test]
    fn unicode_goes_through_the_tables() {
        assert_eq!(call(StdFn::Trim, &[Value::text("\u{3000} a \u{85}")]).unwrap(), Value::text("a"));
        assert_eq!(call(StdFn::Lower, &[Value::text("İ")]).unwrap(), Value::text("i"));
        assert_eq!(call(StdFn::IsAlnum, &[Value::text("Ⅻ٣")]).unwrap(), Value::bool(true));
        assert_eq!(call(StdFn::IsAlnum, &[Value::text("")]).unwrap(), Value::bool(false));
    }

    #[test]
    fn hashes_and_ids() {
        assert_eq!(fnv1a64(b""), 0xcbf29ce484222325);
        assert_eq!(fnv1a64(b"a"), 0xaf63dc4c8601ec8c);
        let id = call(StdFn::IdOfText, &[Value::text("00000000-0000-0000-0000-00000000000A")]).unwrap();
        assert_eq!(call(StdFn::TextOfId, &[id]).unwrap(), Value::text("00000000-0000-0000-0000-00000000000a"));
        assert_eq!(call(StdFn::IdOfText, &[Value::text("nope")]).unwrap(), Value::Null);
    }

    #[test]
    fn faults_are_told_apart() {
        assert_eq!(call(StdFn::Abs, &[Value::int(i64::MIN)]), Err(StdError::Fault("integer overflow".into())));
        assert_eq!(
            call(StdFn::Clamp, &[Value::int(1), Value::int(2), Value::int(1)]),
            Err(StdError::Fault("clamp: lower bound above upper bound".into()))
        );
        assert!(matches!(call(StdFn::Trim, &[Value::int(1)]), Err(StdError::TypeMismatch(_))));
        assert_eq!(
            call(StdFn::SplitOnce, &[Value::text("a=b=c"), Value::text("=")]).unwrap(),
            Value::record(vec![("before", Value::text("a")), ("after", Value::text("b=c"))])
        );
        assert_eq!(call(StdFn::SplitOnce, &[Value::text("abc"), Value::text("")]).unwrap(), Value::Null);
        assert_eq!(call(StdFn::Unwrap, &[Value::Null]), Err(StdError::Fault("unwrapped none".into())));
        assert_eq!(call(StdFn::Unwrap, &[Value::int(3)]), Ok(Value::int(3)));
    }

    fn ints(ns: &[i64]) -> Value {
        Value::from(ns.iter().map(|n| Value::int(*n)).collect::<Vec<_>>())
    }

    fn refused(t: &str) -> Result<Value, StdError> {
        Err(StdError::Fault(t.into()))
    }

    #[test]
    fn a_list_is_edited_in_place() {
        let xs = ints(&[1, 2, 3]);
        let i = Value::int;
        assert_eq!(call(StdFn::ListConcat, &[xs.clone(), ints(&[4])]), Ok(ints(&[1, 2, 3, 4])));
        assert_eq!(call(StdFn::ListConcat, &[ints(&[]), ints(&[])]), Ok(ints(&[])));
        assert_eq!(call(StdFn::Insert, &[xs.clone(), i(0), i(9)]), Ok(ints(&[9, 1, 2, 3])));
        assert_eq!(call(StdFn::Insert, &[xs.clone(), i(3), i(9)]), Ok(ints(&[1, 2, 3, 9])));
        assert_eq!(call(StdFn::Insert, &[ints(&[]), i(0), i(9)]), Ok(ints(&[9])));
        assert_eq!(call(StdFn::RemoveAt, &[xs.clone(), i(1)]), Ok(ints(&[1, 3])));
        assert_eq!(call(StdFn::RemoveAt, &[ints(&[1]), i(0)]), Ok(ints(&[])));
        assert_eq!(call(StdFn::Move, &[xs.clone(), i(0), i(2)]), Ok(ints(&[2, 3, 1])));
        assert_eq!(call(StdFn::Move, &[xs.clone(), i(2), i(0)]), Ok(ints(&[3, 1, 2])));
        assert_eq!(call(StdFn::Move, &[xs.clone(), i(1), i(1)]), Ok(xs.clone()));
        assert_eq!(call(StdFn::Slice, &[xs.clone(), i(1), i(3)]), Ok(ints(&[2, 3])));
        assert_eq!(call(StdFn::Slice, &[xs.clone(), i(3), i(3)]), Ok(ints(&[])));
    }

    #[test]
    fn an_index_out_of_range_is_a_refusal() {
        let xs = ints(&[1, 2, 3]);
        let i = Value::int;
        assert_eq!(
            call(StdFn::Insert, &[xs.clone(), i(4), i(9)]),
            refused("insert: index 4 out of range for a list of 3")
        );
        assert_eq!(
            call(StdFn::Insert, &[xs.clone(), i(-1), i(9)]),
            refused("insert: index -1 out of range for a list of 3")
        );
        assert_eq!(
            call(StdFn::RemoveAt, &[xs.clone(), i(3)]),
            refused("remove_at: index 3 out of range for a list of 3")
        );
        assert_eq!(
            call(StdFn::RemoveAt, &[ints(&[]), i(0)]),
            refused("remove_at: index 0 out of range for a list of 0")
        );
        assert_eq!(
            call(StdFn::Move, &[xs.clone(), i(5), i(9)]),
            refused("move: index 5 out of range for a list of 3")
        );
        assert_eq!(
            call(StdFn::Move, &[xs.clone(), i(0), i(3)]),
            refused("move: index 3 out of range for a list of 3")
        );
        assert_eq!(
            call(StdFn::Move, &[xs.clone(), i(0), i(i64::MIN)]),
            refused("move: index -9223372036854775808 out of range for a list of 3")
        );
        assert_eq!(
            call(StdFn::Slice, &[xs.clone(), i(2), i(1)]),
            refused("slice: 2..1 out of range for a list of 3")
        );
        assert_eq!(
            call(StdFn::Slice, &[xs.clone(), i(0), i(4)]),
            refused("slice: 0..4 out of range for a list of 3")
        );
        assert_eq!(
            call(StdFn::Slice, &[xs, i(-1), i(1)]),
            refused("slice: -1..1 out of range for a list of 3")
        );
    }
}
